  str_loading_e_h_name112 = "Uma câmara confinada dentro da Prisão Illumina onde os prisioneiros são mantidos.",
  str_loading_e_h_name113 = "Um reino secreto onde Victoria escuta \"A Verdade.\"",
  str_loading_e_h_name10004 = "Comunidade Aconchegante",
  str_loading_e_h_name10005 = "Bairro Movimentado",
  str_loading_e_h_name10006 = "Mundo Exterior Aterrorizante",
  str_loading_e_h_name10007 = "Você está pronto, Eve?",
  str_loading_e_h_name20011 = "Onde a justiça prevalece.",
  str_loading_e_h_name20012 = "O berço da espinha dorsal do futuro de Lumópolis.",
  str_loading_e_h_name20013 = "Um luxuoso enclave de nobres.",
  str_loading_e_h_name20014 = "Onde agitação e perigo coexistem.",
  str_loading_e_h_name20015 = "Pronto para começar o próximo julgamento?",
  str_loading_e_h_name80030001 = "A Residência",
  str_loading_e_h_name80030002 = "Ruas Familiares Antes",
  str_loading_e_h_name80030003 = "Um Lugar para Retornar",
  str_loading_e_h_name80030004 = "Mundo Aqua",
  str_loading_e_h_name80040001 = "Rua Comercial Bicontinental",
  str_loading_e_h_name80040002 = "Pequena Longzhou",
  str_loading_e_h_name80040003 = "Porto Comercial Bicontinental",
  str_loading_e_h_name80040004 = "Lenda do Espadachim da Baía dos Pavilhões Gêmeos",
  str_loading_e_h_name80050001 = "Épico do Herói Civil",
  str_loading_e_h_name80050002 = "Civilização Milenar",
  str_loading_e_h_name80050003 = "Fé Milenar",
  str_loading_e_h_name80050004 = "Rivalidade Milenar",
  str_loading_desc1 = "Sob Lumópolis, a terra de vastas sombras, inúmeras pessoas que viviam de comércio e a troca de informações formavam grandes cidades, enquanto forças do subterrâneo são os verdadeiros soberanos desses lugares.",
  str_loading_desc2 = "A região conhecida como Astra é a pérola no círculo do crepúsculo, e para muitos Aurorianos, é o único lugar conhecido como lar, onde existe uma alternância regular de dia e noite para a vida florescer.",
  str_loading_desc3 = "Localizado no frio norte, as pessoas podem viver em paz aqui, graças ao poderoso poder mágico protegendo essa pequena área. Assuntos importantes são decididos pela Rainha Bethlehem.",
  str_loading_desc4 = "A última Crise Darkover começou dezessete anos atrás e foi suprimida por numerosas forças da aliança. No entanto, mesmo nas comunidades unidas, existem disputas e animosidades. Especialmente os Aurorians...",
  str_loading_desc5 = "O único habitat conhecido dos Eclipsitas. Alguns dizem que são relacionados aos inúmeros fragmentos deixados para trás por civilizações antigas. Podemos apenas especular que seja o instinto dos Eclipsitas habitar aqui, ou talvez seja o trabalho de uma organização misteriosa, a Eclipse...",
  str_loading_desc6 = "É um abismo no qual nenhuma luz brilha, a arquitetura é estranha e ameaçadora, e o trabalho maravilhoso dos anciões pode ser encontrado. Numerosos aventureiros vieram a esse lugar, como mariposas atraídas pelo fogo, em busca de relíquias e troféus de uma era desconhecida, apenas para serem enterrados...",
  str_loading_desc7 = "Depois da Crise Darkover envolvendo ataques massivos por Eclipsitas 17 anos atrás, alguns Celestitas escaparam de Eraveil. Soroz também pegou um Celestita e o escondeu no subterrâneo, isolado do mundo.",
  str_loading_desc8 = "Muitos anos atrás, quando Eclipsitas estavam descontrolados, essa cidade subterrânea, mil metros abaixo do chão, salvou inúmeras vidas. As pessoas da Cidade Gannon se organizaram e desenvolveram a tecnologia especial de Lúmina para construir esse sistema de defesa centrado na Cidade Gannon.",
  str_loading_desc9 = "Aurorians, Eclipsitas, Illumina, Lumópolis... Tem muita informação na sua cabeça. O ressurgimento dos Eclipsitas tem alguma relação com a Crise Darkover, de dezessete anos atrás? A jornada pela verdade sempre será repleta de altos e baixos...",
  str_loading_desc10 = "Uma aliança nomádica descentralizada e ruidosa. Seus resistentes membros cheiram como a estrada e o vento, vagando pelo Deserto Rediesel, vivendo uma vida livre e sem preocupações.",
  str_loading_desc11 = "Supostamente, a organização orquestrou a Crise Darkover e o verdadeiro motivo é desconhecido. É composta por Eclipsitas de alto nível e tem absorvido muitos rebeldes de outras raças para um propósito desconhecido. A Eclipse desapareceu sem deixar rastros, após a coalizão das forças das cidades-Estados, na região de Astra, resolver a Crise Darkover...",
  str_loading_desc12 = "Construída em uma ilha flutuante chamada “Azurita”, essa cidade é a fortaleza mais segura no mundo. Conta com um poder hierárquico distinto, um triunvirato entre Governador, o Conselho Ancião dos Nobres, e os Padres do Templo. Os nobres de Lumópolis são dedicados a manter a ordem atual, enquanto o Templo promove adoração ao Sol.",
  str_loading_desc13 = "Uma federação descentralizada, formada por um grande número de assentamentos ao redor da grande subcidade Gannon, localizado na linha de frente contra Eclipsitas. A Federação Illumina adotou um sistema coletivo de liderança, estabelecendo uma forma de sociedade diferente da de Lumópolis.",
  str_loading_desc14 = "Colossus, um legado da civilização antiga. Possui tantos segredos que é dito ser impossível analisar sua estrutura e entender os princípios por trás dela, nem mesmo com o atual conhecimento e o esforço de estudiosos. Muitas não podem sequer serem manobradas diretamente; apenas os Celestitas podem se ligar com a inteligência das Colossus por meio de suas habilidades psíquicas, criando um profundo nível de controle que permite tal operação.",
  str_loading_desc15 = "O caos causado pela Crise Darkover há 17 anos levou à perda de inúmeros objetos misteriosos dos Celestitas. Ninguém sabe o paradeiro deles. Até mesmo seu verdadeiro propósito foi deliberadamente escondido...",
  str_loading_desc16 = "Senhor Sombrio, ou Istvan, é o mais temido de Umbraton. É dito que seu museu pessoal de coleções, o Corredor Suspirante, contém um grande número de itens horripilantes. Se tiver sorte o suficiente de sobreviver aos perigos escondidos atrás dos tijolos e teias, talvez encontre coisas interessantes...",
  str_loading_desc17 = "Os residentes de Umbraton parecem ter dois lados: sorridentes e frios, gentis e rudes. Isso também é uma característica de Umbraton. Desde que você se adapte, esse lugar é o paraíso, caso contrário, será o inferno.",
  str_loading_desc18 = "No continente de Astra, traços de inúmeras relíquias de tempos antigos foram revelados, e a recém-descoberta Torre é uma delas. Todos se surpreendem não apenas com sua altura, mas também seu poder incrível, e as lendas sobre tesouros escondidos ali dentro...",
  str_loading_desc19 = "Aqueles que ganham poder da Luz e lutam com eles são os principais habitantes desse continente. Além deles, alguns grupos podem confrontar os Eclipsitas diretamente.",
  str_loading_desc20 = "Criaturas de origem desconhecida. São os inimigos mortais de todas as comunidades desde o começo da história escrita. Quase ninguém consegue enfrentá-los, exceto os Aurorians.",
  str_loading_desc21 = "Material para criar um sinal de ajuda. Pode ser usado no recrutamento de Aurorians, para que se juntem à aventura. Infelizmente, não existe garantia de quem irá responder ao chamado.",
  str_loading_desc22 = "Parece um piano e os comandos são feitos ao tocar o Painel de Controle da Colossus. Apenas Celestitas compreendem sua linguagem.",
  str_loading_desc23 = "Barreiras naturais e numerosos Colossi garantiram a paz aqui por centenas de anos.\nAssim como as tecnologias Colossi, a origem dos Celestitas está envolta em mistério e é impossível de verificar.\nSe esta paz puder durar para sempre, este lugar florescerá novamente como antes.",
  str_loading_desc24 = "O tempo não curou as cicatrizes de dezessete anos atrás. O que aconteceu naquele dia vive na realidade intensa do presente.\nDesde então, ninguém voltou a este lugar... até hoje.",
  str_loading_desc25 = "Aquele dia coincidiu com um grande festival, e as pessoas estavam despreparadas.\nA queda de Eraveil parece ter sido inevitável, e Schummer foi apenas um catalisador necessário.",
  str_loading_desc26 = "Aviduz já foi uma unidade especial entre as muitos Colossi de Eraveil.\nEnorme e com funções sem igual, possuía um potencial ilimitado.\nPor isso, as exigências para seu Navegador também foram particularmente rigorosas.",
  str_loading_desc27 = "No núcleo da Aviduz está uma cápsula de cura que pode fornecer tratamento de emergência aos feridos.\nSob o cuidado de alguma força misteriosa, Schummer recuperou um poder muito maior do que qualquer um esperava.",
  str_loading_desc28 = "Uma área escura localizada à beira da Noite Eterna. Aqui, os dias são curtos e as noites são longas, e todo o lugar transborda com Darkflow.\nCostumava haver muitos assentamentos aurorianos aqui, mas todos estão abandonados há algum tempo. Ruínas em ruínas continuam a desmoronar, e a vida agitada do passado está coberta de poeira.\nHoje, tudo o que resta são terrenos baldios, ruínas e enxames de Eclipsites, e nenhum auroriano são está disposto a pisar aqui novamente devido ao persistente Darkflow ...",
  str_loading_desc29 = "Uma Cidade Baixa localizada à beira da Noite Eterna que uma vez serviu como ponto de apoio da Federação Illumina contra os Eclipsites.\nNo entanto, depois de uma invasão de Eclipsite há muito tempo, ela foi abandonada.\nDizem que há muitos suprimentos e tecnologias deixados para trás quando os soldados da Illumina recuaram, mas poucos estão dispostos a enfrentar o denso Darkflow e enfrentar o exército Eclipsite para recuperá-los.",
  str_loading_desc30 = "Não há muitos que conheçam esse antigo túnel de fuga, mas é um milagre que ele ainda exista até hoje.\nPode ser o único caminho para a superfície, então é melhor segui-lo.\nDerrote todos os inimigos que encontrar nesta antiga passagem repleta de balas. Você pode simplesmente escapar, e quem sabe, isso pode levá-lo à batalha final.",
  str_loading_h_desc1 = "Esse é o Deserto Rediesel do sul de Astra – um mar infinito de areia dourada que se estende até onde os olhos conseguem ver.\nSob o olhar do sol ardente, essa terra árida e seca é um dos lugares mais inabitáveis de Astra.\nSomente as criaturas mais teimosas e resistentes conseguem encontrar liberdade aqui.",
  str_loading_h_desc2 = "Para chegar ao centro da tempestade da Ravina Olho Rubro, deve-se passar por fortes ventos e chuva incessante.\nA cinza vulcânica, que dizimou a terra, agora atua como fertilizante, enchendo de vida toda essa extensão de verde.\nÉ quase como se aquela antiga tragédia não tivesse acontecido...",
  str_loading_h_desc3 = "A atmosfera desse laboratório de concreto subterrâneo é chata e deprimente por natureza.\nFerramentas cirúrgicas ficam espalhadas sobre bancadas abertas e seus contornos frios e insensíveis refletem um clarão de luz ameaçador.\nMas é apenas num lugar como esse que as flores mais bonitas florescem.",
  str_loading_h_desc4 = "Na memória de Eve, o céu de sua cidade era de um azul claro e sem nuvens.\nSe as coisas não tivessem mudado tão de repente, talvez aquele breve momento de felicidade pudesse ter durado para sempre.\nMas só talvez...",
  str_loading_h_desc5 = "Em um oásis nas profundezas do Deserto Rediesel, há uma rua construída pela Rediesel Wrench.\nEmbora a rua esteja em condições precárias, cada tijolo degradado está repleto de amor.\nEsse humilde pedaço de terra é o lugar mais delicado do mundo.",
  str_loading_h_desc6 = "O hotel Tir é o principal destino de férias da nobreza de Lumópolis.\nÉ o melhor lugar para desfrutar das belas paisagens da Costa Celestial!\nAtualmente, as reservas estão disponíveis com um desconto por tempo limitado.",
  str_loading_h_desc7 = "O Monarca do Oceano é uma cerimônia de sacrifício originada dos Aurorians que viveram nesta costa.\nOs participantes devem aceitar várias provas e concluir desafios complexos.\nAcredita-se que seu triunfo trará bênçãos de bom tempo e abundância de peixes.",
  str_loading_h_desc8 = "Uma antiga lenda conta a história de um castelo que emergiu do mar.\nPara salvar seu povo, um rei aceitou os julgamentos das deusas.\nO tempo passou, a crise já acabou há tempos, mas o Monarca não voltou.",
  str_loading_h_desc9 = "Não está claro quem desejou que este domínio existisse, mas é um vazio preenchido com estranhas visões.\nNele estão os que buscam o poder dos corajosos perdidos e os que anseiam pela oportunidade de escapar de sua servidão.\nAbrace sua maldição e corte suas amarras.",
  str_loading_h_desc10 = "Enfrentando a derrota, Caroline amaldiçoou a todos com o que restava de suas forças.\nE o Monarca que ela desejava ressuscitar pode ter ouvido seu pedido...",
  str_loading_h_desc11 = "Hora dos pedintes se moverem novamente.\nEsses ladrões sombrios emergem da escuridão, apenas para retornar às sombras tão rapidamente quanto apareceram.",
  str_loading_h_desc12 = "No deserto desolado, fica uma torre de vigia da Subcidade de Illumina. Ela esteve aqui desde que Illumina estabeleceu a Subcidade e a Linha Defensiva, testemunhando os confrontos incansáveis dos inabaláveis soldados de Illumina.",
  str_loading_h_desc13 = "Esse é o campo de batalha nas periferias da Subcidade. Os soldados de Illumina levantaram fortes aqui, que dizem serem capazes de parar os avanços da maioria dos Eclipsitas.",
  str_loading_h_desc14 = "Essa estação de transporte está nos portões da Subcidade 24 e é por onde são administrados os bens que entram e saem da cidade. Apesar de ninguém trabalhar aqui agora, você pode ver pelas torres, pelos veículos de transporte e pela grande variedade de bens, que as pessoas tinham uma vida ativa e ordenada.",
  str_loading_h_desc15 = "Uma Subcidade abandonada de Illumina, devastada por um incêndio enorme. Os civis que viviam aqui foram evacuados, e os soldados agora lutam na linha de frente. Os antigos habitantes lutam para continuar a cumprir suas responsabilidades, determinados a voltar para casa um dia.",
  str_loading_h_desc16 = "Em Illumina, até as passagens possuem uma lucidez radiante, brilhando com a luz do aço. Ao ver essa passagem pela primeira vez, ninguém consegue evitar de comentar o quão brilhante ela é.",
  str_loading_h_desc17 = [[
Durante esse festival, os Celestitas praticavam diversos costumes interessantes e decoravam suas casas.
Eles acreditavam que podiam se conectar com a natureza e seus ancestrais por meio desses costumes.]],
  str_loading_h_desc18 = "A história é como uma pena, presa sob uma concha pesada.\nO caminho para o futuro depende de como lidamos com a estrada à frente.",
  str_loading_h_desc19 = "Livre comércio em um livre mercado – tudo é negociado em Umbraton.\nAs guildas são a personificação do comércio e do capital, trazendo enorme vitalidade para Umbraton.",
  str_loading_h_desc20 = "As gangues clandestinas de Umbraton são conhecidas como \"sombras na sombra\". Como atuam de forma duvidosa, não podem se dar ao luxo de se expor publicamente. No entanto, elas sonham em usar sua subversão furtiva para se tornarem um sucesso e serem aceitas na sociedade. Quando nuvens negras se formam acima, elas começam a colocar todos os tipos de operações secretas em ação...",
  str_loading_h_desc21 = "A Represa das Cicatrizes permanece de pé após desastres naturais ou criados, tempestades ou guerras. Ela não só provou sua firmeza ao seu construtor, o Senhor Sombrio, mas também trouxe uma grande sensação de segurança ao povo de Umbraton.",
  str_loading_h_desc22 = "Os nobres de Lumópolis exibem sua riqueza com orgulho, embora sua suntuosa exibição de luxo venha do trabalho árduo das massas comuns que moram na cidade abaixo de Lumópolis. Ainda que seja um mundo à parte dos feudos da nobreza, a vida segue em frente com uma vitalidade calorosa e decidida. Afinal, isso ainda faz parte de Lumópolis. Mesmo com status inferior, as pessoas estão muito melhor do que aqueles que vivem fora dos limites da cidade.",
  str_loading_h_desc23 = "Como centro da civilização Aurorian, Lumópolis se considera a líder das forças do continente. Esse salão foi construído, para mostrar a força e a glória de Lumópolis aos líderes estrangeiros convidados à cidade, a fim de participar das reuniões de importância global. Dessa forma, Lumópolis mantém a vantagem em todas as conferências das quais participam essas forças e toma uma grande parte das decisões, que influenciam todo o continente, de acordo com seus ideais.",
  str_loading_h_desc24 = "Os fogos de artifício do festival envolvem toda a Azurita. Sob uma exibição brilhante, as pessoas se reúnem para desfrutar de uma grande celebração. Como centro da civilização em Astra, Lumópolis merece um dia assim. Mas cada dia deve chegar ao fim.",
  str_loading_h_desc25 = "O clima em Northland faz com que a neve acumule o ano todo. Para quem vive nessa área, a floresta nevada é uma vista conhecida. Quando a luz do amanhecer brilha nas copas das árvores cristalizadas com gelo, os milhares de raios de luz que refratam sem parar tornam-se um símbolo de fé para os residentes de Northland.",
  str_loading_h_desc26 = "Muitos alegam que ele é um lago glacial natural, mas é impossível explicar como esse lago congelado profundo, calmo e liso como um espelho surgiu. Portanto, muitos acreditam que a formação do Lago Espelho é um presente dos céus. Dizem que quando a família real de Northland viajou para o local, eles tiveram uma visão: narcisos florescendo em volta do Lago Espelho, aumentando ainda mais o mistério do lago.",
  str_loading_h_desc27 = "Dizem que o guardião que protege Northland é o primeiro feixe do amanhecer na margem do horizonte, que dispersa a escuridão invasora da terra da noite eterna. Porém, em outras lendas, o verdadeiro poder de Northland está no juramento e determinação de proteger esse lugar. Ambos são mais fortes do que qualquer aurora brilhante e amanhecer glorioso, e ambos são duradouros.",
  str_loading_h_desc28 = "Ruínas inteiras, completamente isoladas do mundo e repletas de edifícios nunca antes vistos.\nParece não haver vestígios dos habitantes originais.",
  str_loading_h_desc29 = "Por razões desconhecidas, as ruínas estão desmoronando rapidamente.\nTanto as máquinas que estão ocupadas consertando as ruínas quanto os Eclipsites que vivem nelas tornaram-se voláteis.",
  str_loading_h_desc30 = "Ainda há muitos segredos não resolvidos nesta cidade.\nA menos que todos já tenham uma resposta em seus corações...",
  str_loading_h_desc31 = "Este núcleo de energia está funcionando há anos além da medida. Está lutando como um paciente moribundo. Cada batida do coração poderia muito bem ser a última.",
  str_loading_h_desc32 = "O centro de dados da Abby. Este módulo biológico louco está constantemente produzindo e aprimorando Eclipsites. Seus gritos irascíveis e horríveis assombraram o centro.",
  str_loading_h_desc33 = "Uma pequena ilha a leste de Astra que é rica em recursos e tem relativamente poucos Eclipsitos. Há um século, Koufu-jou foi construído no centro da Ilha das Nuvens e um general foi enviado pela ilha principal para governar o local. Desde então, as duas ilhas estão em desacordo uma com a outra. Por trás de um passado temido pelos nativos da Ilha das Nuvens, este general está prestes a levar seus segredos e a Ilha das Nuvens para um futuro imprevisível...",
  str_loading_h_desc34 = "O tradicional Festival da Primavera de Cloud Island foi preservado ao longo do tempo. Embora a história e as gerações tenham mudado, as flores de cerejeira permanecem as mesmas.",
  str_loading_h_desc35 = "As Festas da Noite são um evento especial em Koufu-jou, realizado em memória dos espíritos falecidos. Quando as cerejeiras estão florescendo, as pessoas hospedam o Festival Kasuga todos os anos. Todo mundo se fantasia, usa máscara de gato e lanterna, marchando pela rua à noite. Eles acreditam que podem se conectar com o mundo da vida após a morte dessa maneira e ver seus entes queridos falecidos mais uma vez.",
  str_loading_h_desc36 = "Koufu-jou está no lugar mais alto da Cloud Island. Quando as pessoas olham para cima do resto da Ilha das Nuvens, parece que ela está aninhada nas nuvens, aumentando seu mistério e solenidade. Os ancestrais da Ilha das Nuvens construíram Koufu-jou tijolo por tijolo anos atrás, mas hoje, o fogo ardente consumiu tudo. Foi só então que as pessoas começaram a pensar no que realmente queriam. Agora, quem saudou a guerra, e quantos morreram nas chamas ardentes?",
  str_loading_h_desc37 = "Os mortos-vivos assumem formas durante as horas de Yin, criando um campo de força que assombra a Ilha das Nuvens, enquanto o artefato divino moldado durante as horas de Yang possui o puro poder Yang de eliminar todos os espíritos malignos. No entanto, quando Yin e Yang estão nas mãos de uma pessoa gananciosa e egoísta, desejos desenfreados são então transformados em algo mais aterrorizante do que fantasmas.",
  str_loading_h_desc38 = "Localizado na parte sul do Deserto Rediesel, vendavais implacáveis cobrem seus arredores em uma neblina amarelada até onde a vista alcança, pontuada apenas por ossos brancos e árvores mortas sem nenhum vestígio de vegetação à vista. Mas mesmo neste lugar sombrio e desolado, ainda há sinais de vida. Além dos escorpiões-de-fogo e das cobras-de-anel carmesim escondidas nas sombras das rochas, há predadores ainda maiores à espreita no mar de areia. Este é um lugar onde os fracos são engolidos inteiros.",
  str_loading_h_desc39 = "A terra ao redor do vulcão está repleta de arenito preto áspero. Visto de cima, lava ardente desce pelas fissuras da montanha, formando uma espetacular cachoeira de lava na beira de uma ravina. Quanto mais se aproxima do vulcão, mais quente fica o ar, dificultando a respiração. O que é ainda mais surpreendente são os pedaços menores de arenito flutuando no ar devido a forças misteriosas.",
  str_loading_h_desc40 = "Blazing Tooth Canyon, perto da borda da Noite Eterna, recebe o nome de sua paisagem irregular. Suas encostas íngremes parecem mergulhar no chão onde um rio, há muito tempo seco sob o sol escaldante, serpenteia e é coberto de tantas rachaduras que dificilmente pode ser chamado de estrada. Mas talvez seja porque esses recursos atuam como obstáculos intransponíveis que foi designado como o local para a primeira pista de rally da Rediesel Wrench...",
  str_loading_h_desc41 = "Para esconder um cômodo, cubra o portão com tijolos e telhas e encha as janelas com areia e barro. Transforme-o em parte de uma rua ou muro insignificante e limpe-o do mapa para sempre. Um canto deste mundo se foi, mas ninguém sabe. Está reservado exclusivamente para a Verdadeira Ordem. Lumopolis é muito grande, onde um buraco como este passa facilmente despercebido.",
  str_loading_h_desc42 = "De pé atrás da cortina grossa antes do show começar, você deve conter seu coração acelerado, pois este palco não permite que ninguém pare quando a cortina for aberta. A resposta para um desempenho perfeito está apenas na sua próxima tentativa.",
  str_loading_h_desc43 = "É seguro dizer que os fantoches são desprovidos de vida e alma. Mas quando atinge uma pose viva, pode fazer alguém pensar que é mais humano do que os próprios vivos. Talvez seja porque fantasiamos que objetos como esse têm alma.",
  str_loading_h_desc44 = "Se há uma coisa que representa Eraveil, seria o dente-de-leão. Essas pequenas flores brancas e fofas crescem em todo Eraveil, e uma rajada de vento é tudo o que é necessário para criar a ilusão de neve caindo. Alguns não gostam de dentes-de-leão porque sentem que lhes falta fidelidade, sempre criando raízes onde o vento os leva. Mas em Eraveil, você descobrirá que, independentemente da direção do vento, sempre é possível ver grandes grupos de dentes-de-leão suspensos no ar. Eles vêm e vão com o vento, mas sempre permaneceram.",
  str_loading_h_desc45 = "Eraveil é um lugar sereno onde ventos suaves sopram sobre infinitas planícies verdes e o ar é sempre refrescante. Apesar disso, a visão cansa e evoca um vazio que pode ser sentido no fundo, como se algo estivesse faltando. Onde estão os galos cantando ao raiar do dia e a fumaça subindo das chaminés à noite?",
  str_loading_h_desc46 = "Seguindo o guia, você retorna a Eraveil, um lugar com muitas lembranças familiares.\nPor baixo do Eraveil, no entanto, encontra-se um segredo.\nEste segredo é sobre Eraveil, o passado e o futuro, e sobre você.",
  str_loading_h_desc47 = "Escondido no vasto espaço abaixo da Torre Branca está uma entrada que leva ao subsolo!\nVocê pode muito bem ser o primeiro a desbloqueá-lo novamente depois de milhares de anos.\nExplore as ruínas subterrâneas profundas... E lá, você pode encontrar o que está procurando.",
  str_loading_h_desc48 = "O misterioso dispositivo em forma de anel no centro da \"Base de Manutenção Colossus\" abaixo do Eraveil parece ser o centro de controle de toda a base que manteve o vasto complexo funcionando durante todo esse tempo.\nNo entanto, parece que não foi mantido por um longo tempo e não tenho certeza se ainda funciona ...",
  str_loading_h_desc49 = "A existência da torre branca em Eraveil é um segredo em si.\nA alta Torre Branca ressoa com tecnologias antigas que ainda existem hoje. Essa ressonância representa uma ameaça do passado ou uma esperança para o futuro?",
  str_loading_h_desc50 = "O misterioso dispositivo na base subterrânea de Eraveil parece ter o poder de transformar Aurorianos. O conhecimento de como funciona é perdido e ninguém sabe o que realmente pode fazer. Para usá-lo, é preciso considerar os riscos envolvidos...",
  str_loading_h_desc51 = "Você voltou aqui para usar o \"Acorde da Lei\".\nEmbora esse caminho possa ser muito difícil para um Celestita, até mesmo a menor esperança vale a pena manter.",
  str_loading_h_desc52 = "Ambiente harmonioso e paisagem natural... Para um celestita, não há patrimônio melhor do que Cloud Gardens. Há muitas coisas para lidar neste enorme pátio na Torre Branca. Cada existência insignificante em suas mãos se tornará parte do futuro que pertence ao celestita.",
  str_loading_h_desc53 = "A Fonte da Esperança em frente à Hyacinth Tower é o coração de Cloud Gardens. Você pode conversar com seus amigos, soltar o peixe que você pegou na lagoa ou jogar uma moeda de esperança brilhante na lagoa para fazer um desejo cintilante.",
  str_loading_h_desc54 = "A sala mais comum em Cloud Gardens. Tem boa iluminação e excelente ventilação, tornando-se um espaço de habitação ou armazenamento perfeito. No entanto, lembre-se de limpá-lo bem antes de usá-lo.",
  str_loading_h_desc55 = "Sob a colcha bem feita, há roupas sujas que não são lavadas há uma semana. O armário bem embalado está cheio de xícaras que estão prestes a cair. Lanche crocante pela metade Crunches, livros e revistas estão espalhados por todo o lugar... Isso não é normal para o quarto de um menino?",
  str_loading_h_desc56 = "\"Não há família eterna, mas apenas lucro.\" Como muitas famílias antiquadas em Umbraton, todos os tijolos e telhas da casa da família Andersen foram construídos com enormes lucros. O atual Conde Andersen, no entanto, parece ter diferentes preferências de investimento.",
  str_loading_h_desc57 = "Faça com que os convidados de sua família se sintam em casa e inspire medo nos inimigos de sua família. A ordem do mestre deve ser cumprida, não importa o quê. No entanto, as personalidades do mordomo e do mestre são iguais - o mordomo de elite da família Andersen é perfeito e não mostra misericórdia, mesmo quando está testando seu mestre.",
  str_loading_h_desc58 = "Bestas maravilhosas geralmente são encontradas longe das pessoas, vivendo livremente nas montanhas, florestas, desertos, campos de neve ou oceano profundo. Ao contrário dos animais normais, eles podem usar Lumina e possuem várias habilidades ou características únicas. Essas criaturas amigáveis raramente interagem com os aurorianos, mas costumam ajudar em uma crise.\nAo mesmo tempo, no entanto, mudanças em seus habitats e suas próprias deficiências reprodutivas levaram a um declínio em sua população geral, e muitos animais maravilhosos estão agora em perigo.",
  str_loading_h_desc59 = "Onde aparecem bestas maravilhosas, você também encontrará os extrozoólogos nas proximidades. Embora sejam muito mais raros do que bestas maravilhosas, eles são incrivelmente apaixonados por seu trabalho. Eles seguem trilhas de animais maravilhosos até os confins do mundo, mantêm registro de sua ecologia e características e compilam esses registros em livros como seu legado. Eles também ajudam as bestas maravilhosas quando estão em perigo.\nFia está a caminho de se tornar uma extrozoóloga através de seus próprios esforços.",
  str_loading_h_desc60 = "O paradeiro do The Illusionist & Old Bill's Circus sempre foi desconhecido. Recentemente, há palavras que eles foram convidados para a famosa cidade portuária, Harbour City. O apresentador, Jeno, é uma pessoa excêntrica, e todos os seus subordinados têm habilidades únicas. Ele quer dar aos cidadãos locais um grande festival de verão para lembrar.",
  str_loading_h_desc61 = "O senhor da cidade de Harbour City parece bastante obcecado com a Esmeralda. O que poderia estar lá? Que segredos estão escondidos? A agitação da celebração logo diminuirá, e a corrente latente sob o convés logo surgirá...",
  str_loading_h_desc62 = "O caos criado por Elvis parece ter chegado ao fim após sua prisão, mas ninguém sabe realmente por que ele fez tudo isso. As dúvidas no coração de Carleen a deixavam tão triste quanto o clima em Harbor City. Quando a verdade virá à tona? Para chegar ao fundo disso, Carleen e seu grupo ficaram em Harbor City para conduzir investigações. Enquanto isso, parece que Elvis ainda não decidiu seu plano.",
  str_loading_h_desc63 = "O antigo selo foi abalado, despertando o lendário Eclipsite adormecido no fundo do mar. Uma guerra no litoral está prestes a estourar enquanto as ondas varrem a cidade de Harbour. Em face da batalha iminente com Eclipsites, o grupo será capaz de proteger Harbour City? Elvis encontrará uma solução para esta crise?",
  str_loading_h_desc64 = "O Cloudwhale dissipou o Darkflow que penetrava no ar e cortou as nuvens escuras que envolviam Harbour City. Quando o sol brilhou em Harbor City, parecia que tudo havia melhorado, e até mesmo o vento uivante parecia estar dando sinais de parar.",
  str_loading_h_desc65 = "Os Eclipsites invadiram há 12 anos.\nDepois de inúmeras batalhas infernais, isso é o que restou de Euphoria.\nFeridas que nunca cicatrizaram, gradualmente apodrecendo.",
  str_loading_h_desc66 = "Esta cidade está sobrecarregada com muitos pecados do passado.\nEles crescem como tumores em um corpo e devem ser removidos para se recuperar.\nTalvez só então o sol volte a este lugar.",
  str_loading_h_desc67 = "— Foi assim que foi anunciado no jornal. Este edifício nos arredores de Umbraton teve inúmeros proprietários ao longo dos anos. Só recentemente ela passou para a posse dos Andersen, que a transformaram na casa mal-assombrada que é hoje. Foi supostamente construído por um arquiteto excêntrico que foi o cérebro por trás do projeto da escada falsa, portas e janelas mal colocadas. Todos os candelabros e pinturas bizarros eram de seu próprio projeto.",
  str_loading_h_desc68 = "Um porão peculiar fica abaixo do que hoje é conhecido como a Casa Assombrada Andersen. Eu sei que você nunca viu por si mesmo. É possível que mesmo o atual proprietário nunca tenha posto os olhos nele. O último proprietário da casa pôs os pés lá apenas uma vez e vendeu o lugar pouco depois, antes de se mudar para longe, muito longe. Há muitos rumores em torno do porão, mas não acredito em nenhum. Afinal, os vivos não têm como saber a verdade.",
  str_loading_h_desc69 = "O Centro de Pesquisa Illumina é o centro de ciência e tecnologia da Federação Illumina.\nOs pesquisadores aqui são responsáveis por analisar dispositivos tecnológicos antigos e inovar novas tecnologias.\nNo entanto, não há fim para a pesquisa. Você encontrará as informações que procura aqui?",
  str_loading_h_desc70 = "O simulador de campo de batalha feito pelo Illumina Research Center pode levar você a qualquer batalha registrada em seu sistema.\nNão questione a autenticidade das cenas que ele evoca para você: os soldados desesperados, os ferozes eclipsitas, o sol eclipsado pelas chamas da guerra... Tudo o que você vê aqui realmente aconteceu.",
  str_loading_h_desc71 = "Números e ciência são incompreensíveis e distantes. O estranho é que eles podem apresentar emoções e intenções abruptamente de uma forma incomparavelmente precisa diante de nós. Algumas distâncias são ainda mais assustadoras quando podem ser medidas.",
  str_loading_h_desc72 = "Um lugar onde o sol de Lumopolis não brilha, fora da linha de defesa das Cidades Baixas de Illumina. Esta cidade é o último lugar onde os aurorianos se reúnem. Independentemente de seu status e diferenças étnicas, os residentes aqui se fundiram em uma força unificada contra o inimigo para proteger a cultura escondida nesta pequena cidade.",
  str_loading_h_desc73 = "Esses cavaleiros das terras fronteiriças são diferentes daqueles de Lumopolis. Eles rolam tanto no campo de batalha que a areia manchou a seda branca que eles usavam em uma cor diferente de Lumopolis. Eles estão mais acostumados a seguir o fio de suas espadas do que se ajoelhar diante da coroa.",
  str_loading_h_desc74 = "O Colosso que caiu aqui é tão grande.\nUma vez voou livremente com asas que podiam cobrir os céus.\nMas agora ele olha na direção de Eraveil, destinado a nunca mais voltar lá.",
  str_loading_h_desc75 = "Um Colossus equipado com telas gigantes e equipamentos de áudio de cima a baixo.\nOs arqueólogos afirmam que, ao celebrar seus festivais, os caelestitas voavam Eulogoz para o céu e transmitiam canções comemorativas e imagens de dança por Eraveil.\nNo entanto, de acordo com os dados restantes, Eulogoz e seu navegador desapareceram misteriosamente juntos há cerca de cem anos.",
  str_loading_h_desc76 = "Uma besta maravilhosa que pode viver para sempre.\nHá muito pouca informação histórica sobre o Ouroboros, e muitos extrozoologistas realmente acreditam que o Ouroboros é, de fato, uma mera invenção.\nNo entanto, Vic acredita firmemente que existe e acredita que existe alguma conexão inexplicável entre ele e esta besta maravilhosa.",
  str_loading_h_desc77 = "Um Ouroboros dentro de seu ovo pode tecer sonhos de acordo com sua própria vontade e fazer o ciclo dos sonhos continuamente até que passe por seu longo período de incubação com segurança.\nNo passado, pessoas com segundas intenções invadiram deliberadamente o sonho de um Ouroboros para tentar impedi-lo de eclodir para que pudessem alcançar a vida eterna em seu sonho, mas todos falharam sem exceção.\nÉ por isso que você deve pensar duas vezes antes de entrar no sonho de um Ouroboros.",
  str_loading_h_desc78 = "O Shadowind atraca na Baía dos Pavilhões Gêmeos e traz boas novas aos nativos de Longzhou que moram lá. A rota navegada por Shadowind conecta Longzhou e Astra e se tornou uma importante linha de intercâmbio cultural mútuo e comércio entre as duas regiões. Esses navios viajam de um lado para o outro, carregados com mercadorias únicas, iguarias e tesouros de Longzhou, e fornecem a tão procurada passagem de volta para casa para aqueles que ficaram presos longe de casa.",
  str_loading_h_desc79 = "O mar não se rende diante de um exército bem preparado, nem se compadece de um peixe que bate o rabo. Quando a tempestade cai, você simplesmente experimenta os anos infinitos de sua existência em um único momento. Quando estão no centro da tempestade, os marinheiros frequentemente rezam para o peixe-serpente, desejando destinos semelhantes, para mergulhar sem medo nas profundezas do oceano e então se mover com segurança para as águas rasas de sua cidade natal.",
  str_loading_h_desc80 = "O navio afundado está quieto no fundo do oceano, mais sereno neste momento do que em qualquer uma das vezes em que flutuou nas ondas. O mar engole todos os sons, abafando os gritos de vida e deixando apenas uma visão do fim - uma fotografia desbotada lançada na praia. O mar é ilimitado. Pode haver muitos cemitérios de navios como este, mas ninguém presta homenagem a esses túmulos. Esses são os gritos que foram perdidos pelo mundo.",
  str_loading_h_desc81 = "Chegar ao nível dele e julgar o que ele fez ou não fez seria ridículo. Ele não precisa explicar nada a ninguém, então todos os seus problemas são só dele, e sua atitude é tudo o que importa. Ele não se arrepende; em vez disso, algo mais insensível - culpa. Usando uma pessoa para compensar os pecados de cem pessoas... sua culpa não vem de escolha própria, mas lhe dá paz de consciência.",
  str_loading_h_desc82 = "Quando se trata de celebrar o Mooncrown Day, existem diferentes costumes em todo o continente.\nNa Illumina, eles são relativamente discretos e pragmáticos. Eles expressam seu amor dando rolinhos de canela para seus namorados.\nEm Lumopolis, eles se concentram mais no senso de cerimônia e dão um ao outro preciosos trevos vermelhos para representar sua sinceridade.\nEm Northland, eles comemoram com simplicidade, presenteando pequenas garrafas cheias de água do Lago Mirror como lembranças, representando o amor puro.",
  str_loading_h_desc83 = "Um apanhador de sonhos meticulosamente tecido, um requintado pingente de topázio, uma tapeçaria que já foi colecionável entre a nobreza...\nÉ como se você estivesse entrando em uma requintada loja de antiguidades em vez de em um escritório da Courier Union.\nTudo aqui parece demonstrar que o dono desta sala tem um gosto excepcional.\nA maioria das pessoas no Deserto de Rediesel é fanaticamente frugal, mas Jeriah exige apenas o melhor em termos de qualidade de vida e padrões estéticos.",
  str_loading_h_desc84 = "A região central do Deserto de Rediesel é pontilhada de oásis, como estrelas dentro de uma vasta galáxia de areia vermelha.\nAs preciosas águas do deserto alimentaram inúmeras vidas, mas deram origem a terrores inimagináveis, entre os quais o mais famoso é o verme da areia.\nEsses gigantes estão sempre à espreita na areia, prontos para atacar qualquer coisa que passe.",
  str_loading_h_desc85 = "De acordo com os costumes em todo o continente, o Mooncrown Day é um dia para os amantes expressarem seus sentimentos, por isso muitas pessoas realizam casamentos neste dia.\nPara os nobres mais tradicionais, os mensageiros entregam felicidade aos casamentos. Alguns até gastam quantias excessivas de dinheiro convidando esses mensageiros para comparecer.\nPara coibir esse tipo de comportamento, que afeta gravemente a eficiência do trabalho dos correios do continente, o Courier Union vem promovendo outras atividades na tentativa de acabar gradualmente com essa tradição.",
  str_loading_h_desc86 = "Sob a assessoria de Schwartz, o Tribunal de Justiça abriu uma divisão temporária para lidar com disputas amorosas recentes nesta época especial do ano, a fim de garantir a seriedade dos julgamentos do tribunal principal. Entrar na Divisão Romance é como sentar em uma carruagem cujas rodas não param de girar. Antes que o martelo do juiz caia, certifique-se de trazer à luz as evidências mais críticas.",
  str_loading_h_desc87 = "O entusiasmo pelo Mooncrown Day claramente ainda não diminuiu em Lumopolis, já que um grupo de entusiastas de Mooncrown está realizando um salão de amor improvisado. Marcado pelo lançamento de balões de ar quente em forma de lua, tanto plebeus quanto nobres se reúnem sob a lua para dançar, se misturar e curtir os hinos da estação. É também quando sentimentos efêmeros e eternos podem florescer em um piscar de olhos.",
  str_loading_h_desc88 = "Não há ninguém em Lumópolis que não conheça a Escada para os Céus. Com todas as pessoas que passam e visitam este lugar, inúmeras estradas levam à Escadaria para os Céus, você sempre se encontrará caminhando em uma delas. Nesta cidade distintamente estratificada, esta longa escada carrega muitos significados além de um simples \"caminho\". Ao subir esses degraus quando criança, pode-se ver as estrelas; ao escalá-los quando adulto, pode-se até chegar aos Jardins de Lumopolis.",
  str_loading_h_desc89 = "Vamos repensar o que significa \"justiça\". Não tem definição precisa. Geralmente, a maioria das pessoas acredita que \"justiça\" significa fazer as coisas certas. Essas pessoas elegem representantes para falar por elas, e esses representantes condensam suas opiniões em votos. Você descobriu o resultado inevitável desse sistema? A estrutura da nossa sociedade está condenada a definir \"justiça\" pelo número de votos, então agora eu sou \"justiça\".",
  str_loading_h_desc90 = "A pedido do Shadowlord, o Orfanato Umbraton foi reconstruído em seu local original.\nAssim como o Umbraton do passado, o antigo orfanato era uma fossa de corrupção, desprovido do mais leve lampejo de esperança.\nO fogo arrasou o passado e o sol brilhou sem medo sobre o novo solo abaixo.",
  str_loading_h_desc91 = "Hati cresceu aqui com sua mãe.\nEmbora não tivesse permissão para sair, ela teve uma infância feliz, banhada pelo amor maternal.\nO pônei que sua mãe costurou para ela era seu único companheiro de brincadeiras quando criança, e seu colorido livro de imagens era o tesouro transbordante de sua imaginação.\nMas agora, tudo se foi.",
  str_loading_h_desc92 = "A Cidade Baixa já foi não registrada e sem nome, mas foi tomada e reconstruída por alguém muitos anos atrás.\nPosteriormente, foi renomeado como \"Undercity X\" e depois \"Instituto X\" depois que uma série de instalações de pesquisa foram estabelecidas.\nInfelizmente, o local acabou sendo destruído por um incêndio.",
  str_loading_h_desc93 = "Sob a jurisdição do Professor Ulysses de Illumina, o Arquivo armazena inúmeras informações confidenciais.\nO peso da história por trás de cada fragmento de dados é desconhecido, deixando a verdadeira profundidade dos segredos enterrados.",
  str_loading_h_desc94 = "O método de modificação mais eficaz descoberto até agora é combinar vários métodos de aprimoramento que tiveram sucesso comprovado no mesmo objeto experimental.\nPrecisamos apenas de uma mente forte para produzir um resultado bem-sucedido.",
  str_loading_h_desc95 = "O Exercício Militar visa proporcionar um palco para que todos os participantes aprendam, cooperem e compitam.\nExistem duas fases: preparação do curso e avaliação final.\nA equipe vencedora terá a oportunidade de participar de uma partida de exibição com o Grand Marshal of Illumina.",
  str_loading_h_desc96 = "O significado da vitória na batalha nunca deve ser posto em dúvida.\nA batalha incorpora a persistência, a responsabilidade e o heroísmo inabalável de cada auroriano diante da escuridão enquanto nos esforçamos para defender a luz da esperança sem vacilar.",
  str_loading_h_desc97 = "Uma bola de cristal especial desenvolvida por Boaz, um lendário mestre de adivinhação de Northland.\nUma vez ativado com o Lumina, ele registra automaticamente todos os eventos que ocorrem dentro de um determinado intervalo do ativador ao longo do dia.\nO ativador só precisa injetar Lumina mais uma vez para transportar a si mesmo ou aqueles que tocam para o Cristal da Memória Eterna e revisitar o que aconteceu naquele dia.",
  str_loading_h_desc98 = "Para comemorar o Schwartz contribuição da família para Lumopolis, a população da cidade decidiu espontaneamente fazer uma festa no dia do primeiro ancestral do Schwartz família tornou-se o Senhor da Cidade. Com o tempo, esse dia se tornou feriado oficial de Lumópolis.\nO Schwartz a família sempre realiza desfiles, celebrações, jantares sociais e outros eventos neste dia.\nNo entanto, desde a Crise de Darkover, a escala das festividades diminuiu gradualmente.",
  str_loading_h_desc99 = "Milhares de anos atrás, os ancestrais da família Kartima assinaram um contrato com os dragões. Por milênios, os Dragonkin despertos receberam seus próprios dragões, jurando ser leais uns aos outros para sempre e sacrificar incondicionalmente suas vidas e poder uns pelos outros. No entanto, a fim de se misturar à sociedade auroriana, a família Kartima passou a considerar os Dragonkin despertos como estranhos e os proibiu de se reproduzir. Por que suas atitudes mudaram tão repentinamente ainda está para ser respondido. A única coisa que pode ser confirmada é que Mime Kartima, o líder da família, convocou os dragões novamente. Mas daquele dia em diante, sua família começou a declinar completamente.",
  str_loading_h_desc100 = "\"Você pode ter muitas perguntas em mente, e não posso garantir que tenha todas as respostas. Esta jornada deve ser curta, então eu recomendo que você valorize esta experiência fugaz acima de tudo.\"",
  str_loading_h_desc101 = "Nascido em família de indivíduos altamente educados, Joshua é uma mulher notável e experiente que se destaca nos estudos e nas lutas. Seu pai era um estudioso conhecido que ensinou Daniel quando ele era jovem. Foi assim que eles se conheceram e acabaram se tornando um casal que superou a barreira da classe. A história de amor deles é um clássico da nova era de Lumópolis, que inspira inúmeros jovens com anseios e expectativas para o futuro. Joshua correspondeu às expectativas do povo, apresentando-se com uma imagem tão perfeita quanto a da Santa Madre, o que aumentou sobremaneira a confiança política do povo na Schwartz família.\nEra assim que as coisas eram até aquele acidente.",
  str_loading_h_desc102 = "Ela já teve um nome próprio, mas agora ela é chamada Joshua ou o Filho de Montague. Ao contrário do atual City Lord, o ex-City Lord, pai de Daniel, era um tirano. Através de uma tirania sem precedentes, ele mudou a classe que havia reforçado seus pontos de vista em Lumopolis por cem anos e também expurgou seus oponentes de forma extremamente cruel. Joshua é um sobrevivente da Casa Montague.\nAlguns conspiradores argumentaram com base nesses sobreviventes para estabelecer uma organização com o objetivo de derrubar o Schwartz família. No entanto, era apenas mais uma luta política por mais poder, e ninguém realmente se importava com a dor dos sobreviventes. A raiva insaciável em seus olhos é apenas uma ferramenta aos olhos dos outros.",
  str_loading_h_desc103 = "O País das Maravilhas Denuo, localizado no coração do Deserto Rediesel e abraçado por um desfiladeiro tranquilo, marca a primeira fase do desenvolvimento do Denuo Valley Resort.\nA Rediesel Wrench desempenhou um papel importante no projeto de várias atrações durante a criação do parque, garantindo uma experiência emocionante e desafiadora para todos os visitantes. Vale ressaltar que a roda-gigante permanece aberta durante a noite, permitindo que os hóspedes desfrutem de um romântico espetáculo de fogos de artifício enquanto a utilizam.",
  str_loading_h_desc104 = "Situado ao lado do país das maravilhas, o Denuo Resort Hotel se apresenta como um magnífico castelo que surge graciosamente do país das maravilhas. \nA paisagem de jardinagem distinta na entrada principal incorpora a essência cultural do Vale Denuo e o profundo respeito dos desenvolvedores pela natureza. Vale a pena destacar os artefatos feitos à mão exibidos no saguão e terraço do hotel, criados por artesãos locais que mostram seus extraordinários talentos. Todo o hotel é como um museu, contando a fascinante história do Vale Denuo e a encantadora lenda da Deusa Denuo para cada hóspede valorizado.",
  str_loading_h_desc105 = "O Vale Denuo é considerado uma joia intocada, ostentando uma disposição geográfica vantajosa e uma paisagem natural pitoresca.\nSegundo lendas locais, um misterioso desastre natural atingiu o desfiladeiro, destruindo uma vila inteira. Esse evento serviu como um lembrete profundo da natureza, levando os desenvolvedores a priorizar a restauração e preservação ecológica durante todo o processo de desenvolvimento. Agora, o Vale Denuo prospera como um santuário florescente, proporcionando um refúgio harmonioso para uma abundante e fascinante vida selvagem e plantas.",
  str_loading_h_desc106 = "O Denuo Valley Resort Hotel está equipado com sistemas de purificação de ar de última geração. Para minimizar os ruídos gerados durante a circulação do ar, o proprietário do resort seguiu o conselho da equipe e construiu uma câmara subterrânea para acomodar a maquinaria de grande porte.\nMal sabem eles que, atrás de uma porta secreta no quarto, há um túnel misterioso e escondido. Armazenados ali estão itens que parecem carregar uma história distante e fascinante.",
  str_loading_h_desc107 = "A história da Prisão Illumina atravessa as eras, estabelecida com o objetivo inicial de garantir a segurança da federação, penalizar comportamentos criminosos e promover introspecção e reforma entre os infratores.\nOs detentos são classificados em diferentes categorias e níveis dentro da prisão com base em seu grau de perigo, na natureza de seus crimes e na duração de suas sentenças. Normalmente, o comitê nomeia diretamente a equipe de gerenciamento das prisões de alta segurança. Qualquer pessoa que entre nessas instalações de alta segurança deve fornecer documentação válida.",
  str_loading_h_desc108 = "O Forte Lumo é o lar dos primeiros exilados de Lumópolis, incluindo cavaleiros, residentes e seus descendentes, todos governados pelos nobres locais de Lumópolis. O atual Senhor da Cidade, Dietrich, acumulou riqueza nos últimos anos através da mineração de minérios e estabeleceu um exército, concedendo-lhe considerável influência sobre as cidades da superfície de Lumópolis.\nDentro do Forte Lumo, há uma igreja independente e um setor de infraestrutura que, em tempos de guerra, estão comprometidos em proteger os residentes de Lumópolis.",
  str_loading_h_desc109 = "Liberada pelo Eclipsita Mudbundle, a lama contaminada varre a terra como uma maré de obsidiana. Onde quer que toque o solo, um forte chiado corrosivo irrompe, seguido pelo desmoronamento do solo e pelo murchamento das plantas. Um poderoso fedor de decomposição paira no ar enquanto o pântano se expande rapidamente, prendendo seres inocentes em seu alcance.\nMudbundle espreita nas profundezas da lama, capaz de movimentos ágeis e ataques contra os Aurorianos. Por outro lado, os Eclipsitas aproveitam o Fluxo Escuro dentro da lama para aumentar seu poder ofensivo.",
  str_loading_h_desc110 = "Até onde sabemos, o Warp provavelmente é um poderoso Fluxo Escuro originário do Eclipse. Cada vez que uma equipe presa nele avança uma certa distância, eles sempre se encontram de volta ao ponto de partida. A verdadeira natureza dessa arte é envolta em mistério.\nEste 'ponto de partida' refere-se ao centro de um espaço circular fixo, restringindo o movimento do grupo dentro de seu raio. Isso deixa os Aurorianos com uma constante sensação de correr em círculos, presos até mesmo em uma ilusão de loops infinitos.",
  str_loading_h_desc111 = "O Forte Lumo é o lar dos primeiros exilados de Lumópolis, incluindo cavaleiros, residentes e seus descendentes, todos governados pelos nobres locais de Lumópolis. O atual Senhor da Cidade, Dietrich, acumulou riqueza nos últimos anos através da mineração de minérios e estabeleceu um exército, concedendo-lhe considerável influência sobre as cidades da superfície de Lumópolis.\nDentro do Forte Lumo, há uma igreja independente e um setor de infraestrutura que, em tempos de guerra, estão comprometidos em proteger os residentes de Lumópolis.",
  str_loading_h_desc112 = "O design das celas da Prisão Illumina segue os padrões e comodidades estabelecidos, garantindo uma supervisão eficaz dos detentos e medidas de segurança. Cada cela possui espaço de armazenamento para que os condenados guardem seus pertences pessoais, variando de pequenos a médios recipientes, roupas e materiais de leitura. Instalações de iluminação e ventilação também estão presentes para garantir conforto e segurança dentro da cela.\nInspeções e manutenções regulares são fundamentais para as celas da prisão, garantindo a manutenção contínua dos padrões de segurança e higiene. Rumores sugerem que esta instalação também detém criminosos de outras facções.",
  str_loading_h_desc113 = "Um domínio que transcende o reino das entidades materiais, aparentemente acessível apenas por caminhos únicos. Os líderes da True Order afirmam ter recebido revelações do Senhor da Verdade neste exato local.\nDentro deste território secreto, a diferenciação entre luz e escuridão se torna difícil de perceber, já que algo cintilante em carmesim parece substituir o ar comum, fazendo com que os Aurorians que chegam aqui pela primeira vez experimentem sensações indescritíveis - suspensão do corpo, intensa compressão e além.",
  str_loading_N33_Cname_01 = "Denuo País das Maravilhas",
  str_loading_N33_Cname_02 = "Hotel Resort",
  str_loading_N33_Cname_03 = "Vale Denuo",
  str_loading_N33_Cname_04 = "Porão",
  str_loading_N33_Ename_01 = "Um luxuoso país das maravilhas aninhado no coração do Deserto Rediesel.",
  str_loading_N33_Ename_02 = "Um resort hotel ultra-magnífico.",
  str_loading_N33_Ename_03 = "Uma região de cânion não desenvolvida dentro do Denuo Valley Resort.",
  str_loading_N33_Ename_04 = "Um porão subterrâneo no hotel, abrigando equipamentos de ventilação e medidas de isolamento acústico.",
  str_loading_N33_des_01 = "O País das Maravilhas Denuo, localizado no coração do Deserto Rediesel e abraçado por um desfiladeiro tranquilo, marca a primeira fase do desenvolvimento do Denuo Valley Resort.\nA Rediesel Wrench desempenhou um papel significativo no projeto de várias atrações durante a criação do parque, garantindo uma experiência emocionante e desafiadora para todos os visitantes. Como um mimo especial, ao pôr do sol, todos os convidados são convidados a pegar a roda gigante e assistir a um espetáculo super romântico de fogos de artifício!",
  str_loading_N33_des_02 = "Situado ao lado do País das Maravilhas Denuo, o Denuo Resort Hotel se apresenta como um magnífico castelo que surge graciosamente do país das maravilhas. \nA distinta paisagem de jardinagem na entrada principal incorpora a essência cultural do Vale Denuo e o profundo respeito dos desenvolvedores pela natureza. Vale a pena destacar os artefatos feitos à mão exibidos no grandioso saguão e terraço do hotel, criados por artesãos locais que mostram seus extraordinários talentos. No geral, o hotel se assemelha a um pequeno museu, narrando a rica história da Vila Denuo e a lenda da Deusa Denuo para cada hóspede querido.",
  str_loading_N33_des_03 = "O Vale Denuo é considerado uma joia intocada, ostentando uma disposição geográfica vantajosa e uma paisagem natural pitoresca.\nSegundo lendas locais, um misterioso desastre natural atingiu o desfiladeiro, destruindo uma vila inteira. Esse evento serviu como um lembrete profundo da natureza, levando os desenvolvedores a priorizar a restauração e preservação ecológica durante todo o processo de desenvolvimento. Agora, o Vale Denuo prospera como um santuário florescente, proporcionando um refúgio harmonioso para uma abundante e fascinante vida selvagem e plantas.",
  str_loading_N33_des_04 = "O Denuo Valley Resort Hotel está equipado com sistemas de purificação de ar de última geração. Para minimizar os ruídos gerados durante a circulação do ar, o proprietário do resort seguiu o conselho da equipe e construiu uma câmara subterrânea para acomodar a maquinaria de grande porte.\nMal sabem eles que, atrás de uma porta secreta no quarto, há um túnel misterioso e escondido. Armazenados ali estão itens que parecem carregar uma história distante e fascinante.",
  str_loading_h_desc10004 = "Eve nasceu e cresceu no deserto de Rediesel.\nEla vive em uma comunidade de caravanas com seu pai robusto e sua mãe carinhosa.",
  str_loading_h_desc10005 = "Eve sempre se perguntou sobre o nome estranho da rua... mas tudo bem.\nTem lojas legais e a clínica do médico.\nIsso é tudo que importa!",
  str_loading_h_desc10006 = "Na memória de Eve, ela nunca havia estado em outro lugar além da área da caravana e da Rua Cauda.\nAgora, tendo arrombado o portão de ferro para o mundo exterior, seus pais provavelmente lhe dariam uma lição séria se soubessem.\nAlém disso... veja, o mundo lá fora é realmente assustador.",
  str_loading_h_desc10007 = "A paisagem muda continuamente diante de seus olhos, como um belo, mas intangível conto de fadas, expondo abruptamente suas presas flamejantes.\nA ilusão desmoronará como montanhas eventualmente, então continue seguindo em frente...",
  str_loading_h_desc20011 = "\"Desde a infância, Irridon tem alimentado um profundo desejo de trabalhar na Corte de Justiça.\nQuanto às razões específicas... parece que até mesmo a própria Irridon tem dificuldade em se lembrar delas.\"",
  str_loading_h_desc20012 = "\"Famílias nobres de alta estatura geralmente não enviam seus filhos para a Dawn Academy para estudos; em vez disso, preferem contratar os serviços dos melhores tutores particulares.\nNo entanto, o pai de Irridon desviou-se da norma. Ele esperava que Irridon pudesse aprender desde cedo como se destacar entre as massas.\"",
  str_loading_h_desc20013 = "\"Da casa de Irridon nos Jardins de Lumópolis, são algumas curvas e reviravoltas seguidas por uma descida pela longa Escadaria para os Céus para chegar ao Pátio de Lumópolis.\nAos olhos de Irridon, o Pátio não parece tão diferente dos Jardins.\nNo entanto, para muitos dos colegas de escola de Irridon, escalar a escadaria entre a classe do Pátio e a classe dos Jardins era como uma missão impossível.\"",
  str_loading_h_desc20014 = "\"Durante os primeiros anos de Irridon, ela teve poucas oportunidades de se aventurar na Baixa Lumópolis.\nSegundo seu pai, aquele lugar estava repleto de nobres menores e pessoas comuns, o que ele temia que pudesse influenciar negativamente a criança.\"",
  str_loading_h_desc20015 = "Sobre a superfície tranquila da água, anéis concêntricos de ondulações douradas se formam um após o outro.\nOs reflexos na água se contorcem gradualmente pelas ondulações, quase como se houvesse um mundo fantástico e colorido ali dentro.",
  str_loading_h_desc80030001 = "Connolly prefere chamar o lugar de \"residência\" em vez de \"lar.\"",
  str_loading_h_desc80030002 = "As ruas parecem estar envolvidas em uma névoa etérea sob a luz cintilante e borrifante, com vidas aquáticas e moradores parecidos com peixes perambulando por elas.",
  str_loading_h_desc80030003 = "Comparado com o sótão escuro e frio, o lugar revigorava Connolly e trazia calor e apoio. Para Connolly, finalmente há uma sensação de pertencimento e um lugar para retornar.",
  str_loading_h_desc80030004 = "Aqui, uma cidade fantástica localizada no fundo do mar que se assemelha ao país das maravilhas dos contos de fadas.\nConnolly mergulha neste mundo aquático, e será que ela conseguirá navegar por correntes tumultuadas e encontrar amigos próximos?",
  str_loading_h_desc80040001 = "O lado oeste de Twin Pavilions Bay é gerenciado por Umbraton. Esta área é semelhante a outras cidades de Astra em termos de estilo arquitetônico, mas parece mais exótico devido à adição de decorações de Longzhou.",
  str_loading_h_desc80040002 = "O lado leste de Twin Pavilions Bay está sob a jurisdição da Guilda Lin, e há um distrito chamado Pequeno Longzhou, que é projetado para parecer exatamente com Longzhou, ao lado do porto.",
  str_loading_h_desc80040003 = "A Twin Pavilions Bay possui vários portos com um grande número de docas e navios. Ela assume a importante responsabilidade das operações de transporte entre Astra e Longzhou e está sempre pronta para receber navios e cargas de todo o mundo.",
  str_loading_h_desc80040004 = "Há muito, muito tempo atrás, havia um fraco espadachim amaldiçoado que empunhava uma grande espada capaz de derrotar qualquer demônio e vencer qualquer inimigo. O espadachim não era movido por dinheiro ou fama e estava em uma busca obstinada para encontrar e quebrar todos os tipos de maldições estranhas. Será que ela conseguirá trazer seu próprio DAWN após exterminar todas as maldições do mundo?",
  str_loading_h_desc80050001 = "Um herói corajoso e bem-humorado surgindo dos civis, líder da Legião Northwind que sempre se sacrifica voluntariamente pelo reino e seu povo. Mas alguém já se aprofundou em seu coração para entender os fardos que ele carrega, sua angústia milenar?",
  str_loading_h_desc80050002 = "Antes desta terra ser conhecida como Astra, ela abrigava brotos dispersos das civilizações Aurorianas. Entre eles estava um reino, cujos vestígios há muito se transformaram em pó, mas suas lendas perduram até hoje.",
  str_loading_h_desc80050003 = "Erguendo-se no centro da cidade, uma estrutura majestosa consagra as crenças compartilhadas de todos no reino. Diferente da Lumópolis de hoje, este lugar sagrado não rejeitava refugiados empobrecidos há mil anos atrás.",
  str_loading_h_desc80050004 = "Apenas verdadeiros guerreiros podem entrar na arena, mostrando seu poder diante do público, recebendo uma chuva de flores e aplausos...",
  str_loading_N35_Cname_01 = "Ruínas Subterrâneas",
  str_loading_N35_Cname_02 = "Northland",
  str_loading_N35_Cname_03 = "Zarya",
  str_loading_N35_Ename_01 = "Ruínas de uma era antiga.",
  str_loading_N35_Ename_02 = "A Terra do Gelo e da Neve, Origem dos Aurorianos",
  str_loading_N35_Ename_03 = "Donzela Congelada",
  str_loading_N35_des_01 = "Este local não existe em nenhum mapa e está ausente da maioria dos guias de exploradores. Essas ruínas estão repletas de inúmeros perigos, como se desafiassem todos que se aproximam a avançar ainda mais. Quase parece que, quanto mais fundo você vai, mais claramente você pode ouvir um som mecânico, desprovido de todas as emoções e aterrorizante o suficiente para fazer qualquer intruso fugir. Se você continuar seguindo em frente, o que encontrará nas profundezas?",
  str_loading_N35_des_02 = "Northland nasceu na neve e perdura através da geada. Sob a guarda do Queen, os Aurorianos protegem Northland por gerações. Agora, como no passado, mesmo que precisem sacrificar suas vidas ou enfrentar uma solidão inimaginável, eles nunca se esquivam dessa responsabilidade. Mas lembre-se, embora Northland seja o berço dos Aurorianos, não é o berço de toda a civilização.",
  str_loading_N35_des_03 = "Cem anos é mais do que uma vida inteira para a maioria dos Aurorianos, mas para Zarya, as tristezas e arrependimentos de um século atrás parecem como se fossem ontem. Aprisionada neste túmulo implacável de gelo por cem anos, ela finalmente foi libertada. No entanto, quem a libertará da geada gelada e das dúvidas persistentes congeladas no fundo de seu coração?",
  str_loading_N36_Cname_01 = "Umbraton",
  str_loading_N36_Cname_02 = "Posto Avançado Illumina",
  str_loading_N36_Cname_03 = "Deserto Rediesel",
  str_loading_N36_Ename_01 = "\"Um centro de negócios e inteligência.\"",
  str_loading_N36_Ename_02 = "\"Repila os inimigos, abrace os que pensam como você.\"",
  str_loading_N36_Ename_03 = "\"Deserto, o verdadeiro reino da liberdade.\"",
  str_loading_N36_des_01 = "Localizada abaixo da cidade de Lumópolis, Umbraton é um centro de comércio e finanças, mas também abriga crimes, corrupção e enganação. No entanto, ao interagir com os moradores locais, você descobrirá que nem todos em Umbraton são moralmente falidos. Há algumas pessoas realmente boas aqui, como o proprietário do Restaurante Liu e o chefe da Guilda Cloudrover.",
  str_loading_N36_des_02 = "Esta é uma área crucial para defender contra os Eclipsitas. Os soldados estacionados aqui são responsáveis não apenas por repelir ataques Eclipsitas, mas também por proteger Illumina e realizar patrulhas de rotina nas regiões próximas e rotas comerciais. De tempos em tempos, esses soldados organizam festas comemorativas. Independentemente de suas origens, desde que você não tenha causado problemas antes ou tenha ajudado Illumina, eles estenderão um convite a você.",
  str_loading_N36_des_03 = "Dentro da vasta extensão do Deserto Rediesel, você encontrará muitas criaturas peculiares além dos Eclipsitas, e talvez até vislumbre os lendários dragões. Mas ainda assim, quando as pessoas mencionam o Deserto Rediesel, a primeira coisa que vem à mente é a Rediesel Wrench liderada por Sinsa. Seus membros frequentemente atravessam o deserto em seus veículos, vivendo uma vida despreocupada e agradável.",
  str_loading_c_h_name10001 = "Baía dos Pavilhões Gêmeos",
  str_loading_c_h_name10002 = "Porto de Twin Pavilions Bay",
  str_loading_e_h_name10001 = "Um porto crucial conectando Astra e Longzhou.",
  str_loading_e_h_name10002 = "Este porto movimentado nunca dorme, com navios mercantes atracando a toda hora.\nEssas embarcações, carregadas com o peso tangível das esperanças e sonhos das pessoas, pontuam o fluxo e refluxo da vida aqui.",
  str_loading_h_desc10001 = "Aninhada na foz do Rio Dourado, Twin Pavilions Bay era uma vez um simples sussurro de uma cidade. Seu destino foi irrevogavelmente alterado anos atrás com a chegada do primeiro navio mercante de Longzhou, iniciando sua transformação em uma metrópole vibrante.\nA cidade é um estudo notável de contrastes: a metade leste, aninhada contra o mar e o porto, está sob a administração do Lin Guild, suas veias arquitetônicas pulsando com o estilo Longzhou; a metade oeste, administrada por Umbraton, apresenta uma imagem espelhada de Umbraton em sua paisagem urbana.",
  str_loading_h_desc10002 = "O Porto da Baía dos Pavilhões Gêmeos, moldado pela incessante maré de navios mercantes, possui um emaranhado de ruas que ecoam o estilo Longzhou, pulsando com o ritmo do mercado.\nPequenas lojas, servindo principalmente como refúgio para marinheiros, pontuam a paisagem, intercaladas com restaurantes acessíveis, pousadas e ocasionais vendedores ambulantes.\nA Ponte Dourada, um distante contorno, funciona como um fio unificador entre as metades leste e oeste da cidade.",
  str_loading_N37_Cname_01 = "Guilda Cloudrover",
  str_loading_N37_Cname_02 = "Clínica Sem Nome",
  str_loading_N37_Cname_03 = "Lobos Negros",
  str_loading_N37_Ename_01 = "Uma das guildas mais prósperas e famosas de Umbraton",
  str_loading_N37_Ename_02 = "Clínica subterrânea confiável",
  str_loading_N37_Ename_03 = "Gangue emergente rapidamente em Umbraton",
  str_loading_N37_des_01 = "Uma guilda fundada por Sheol.\nEm poucos anos, cresceu de uma loja móvel desconhecida para uma das principais guildas de Umbraton.\nA Guilda Cloudrover não alcançou essa façanha por acaso. Afinal, aqui você pode comprar tudo o que pode imaginar - e mais.\nAté você já se perdeu entre suas opções, não é?",
  str_loading_N37_des_02 = "Uma pequena clínica nos subúrbios remotos de Umbraton, que ninguém sabia quando foi inaugurada.\nO médico e o assistente nunca revelaram seus nomes, então todos os chamavam de \"Doutor Sem-nome\" e \"Assistente Sem-nome\".\nApesar do mistério, os moradores pobres das proximidades ainda procuram tratamento em massa, considerando o quão barato e bom o médico é.",
  str_loading_N37_des_03 = "Em Umbraton, inúmeras pequenas gangues se formaram pela necessidade de autoproteção, embora aquelas que não apenas se destacaram, mas continuam a expandir como os Lobos Negros, sejam poucas e raras.\nAlguns afirmam que os Lobos Negros têm o apoio de uma certa guilda importante para agir tão ousadamente como fazem, mas a gangue nunca dá uma resposta direta a esse boato.\nTalvez seja apenas porque ninguém nunca fez essa pergunta abertamente.",
  str_loading_N38_Cname_01 = "Baía dos Pavilhões Gêmeos",
  str_loading_N38_Cname_02 = "Shadowind",
  str_loading_N38_Ename_01 = "Porto Comercial Bicontinental",
  str_loading_N38_Ename_02 = "Embarcação Mecanizada do Oceano",
  str_loading_N38_des_01 = "Originalmente uma pequena vila de pescadores no lado leste de Umbraton, evoluiu para um porto comercial com a chegada dos navios mercantes de Longzhou. Atualmente, o lado oeste da atual Baía dos Pavilhões Gêmeos é administrado por Umbraton, compartilhando estilos arquitetônicos com outras cidades de Astra. O lado leste está sob o controle da Guilda Lin, apresentando uma rua e um porto de tema oriental, semelhantes ao estilo de Longzhou.",
  str_loading_N38_des_02 = "Um navio oceânico de última geração financiado e construído pela Lin Guild.\nProjetado com a adição de maquinário do Reino Ye, supera os navios tradicionais em durabilidade e potência. Além disso, possui um dispositivo para operações de salvamento subaquático. Esta embarcação transportará navegadores, Xuan Ji e outros para o mar profundo, aventurando-se em reinos inexplorados.",
  str_loading_N39_Cname_01 = "Guilda Cloudrover",
  str_loading_N39_Cname_02 = "O Poço",
  str_loading_N39_Cname_03 = "Guilda Continental",
  str_loading_N39_Ename_01 = "Uma das guildas mais prósperas e famosas de Umbraton",
  str_loading_N39_Ename_02 = "Um local de entretenimento para a nobreza.",
  str_loading_N39_Ename_03 = "Uma guilda emergente baseada fora de Umbraton.",
  str_loading_N39_des_01 = "Uma guilda fundada por Sheol. Em apenas alguns anos, ela se expandiu de uma loja móvel sem nome para uma das guildas mais poderosas de Umbraton.\nHoje, a Guilda Cloudrover até possui um enorme navio aéreo que incorpora viagens, compras, lazer e férias, tudo em um só lugar!\nA capacidade da Guilda Cloudrover para tais grandes realizações não é sem motivo. Afinal, qualquer produto imaginável (e até inimaginável) pode ser comprado através deles.Até você já se perdeu em suas consideráveis seleções, não é?",
  str_loading_N39_des_02 = "Na superfície entre Umbraton e Lumopolis existe uma grande extensão de terra outrora conhecida como \"O Poço\". Há muito tempo, servia como um teatro de esportes sangrentos para os nobres de Lumopolis. \nAqui, eles lançavam cem criminosos endurecidos no Poço e os forçavam a se matar para seu divertimento; a última pessoa de pé receberia um perdão total, bem como recompensas generosas do nobre que os patrocinou. Com o tempo, surgiram vários lutadores de Umbraton, gladiadores que entraram voluntariamente no \"Pit\" em busca de riqueza e glória.\nAntes da Crise de Darkover, os nobres já haviam começado a recuar lentamente para a segurança de Lumopolis, e o \"Pit\" entrou em declínio; no entanto, sua cultura de \"força acima de tudo\" persistiu e se tornou o status quo em Umbraton. Em breve, anéis de luta ilegais buscando imitar a glória do Pit surgiram por toda a cidade, atraindo uma enorme quantidade de atenção.",
  str_loading_N39_des_03 = "Uma guilda em grande escala que surgiu fora de Umbraton. Sua líder é uma mulher misteriosa que raramente mostra o rosto em público.\nRaramente as guildas veem esse nível de crescimento rápido sem depender das vantagens geográficas e logísticas de Umbraton, no entanto, a Guilda Continental conseguiu alcançá-lo de alguma forma.\nComo o nome sugere, a influência da Guilda Continental se estende a quase todas as pequenas cidades e vilas na terra de Astra.",
  str_loading_c_h_name121 = "Algol's Lab",
  str_loading_c_h_name122 = "Antiga Câmara Illumina",
  str_loading_c_h_name123 = "Acima da cidade de Gannon",
  str_loading_c_h_name124 = "Armazém Zero",
  str_loading_c_h_name125 = "Fissura Desconhecida",
  str_loading_c_h_name126 = "Rio Pristino",
  str_loading_e_h_name121 = "Um escritório da Illumina que é tanto de alta tecnologia quanto acolhedor.",
  str_loading_e_h_name122 = "Um antigo laboratório da Illumina envolvido em suspeitas e controvérsias.",
  str_loading_e_h_name123 = "Como o amanhecer, mas também como o pôr do sol.",
  str_loading_e_h_name124 = "Um misterioso armazém fora dos registros em Illumina.",
  str_loading_e_h_name125 = "Fissura despedaçada e afundando de profundidade e escuridão desconhecidas.",
  str_loading_e_h_name126 = "Rio torcido e cintilante com charme enigmático.",
  str_loading_h_desc121 = "Este laboratório de arquitetura mista é o escritório privado do cientista da Illumina, Algol. Um local que combina tecnologia e conforto é raro na Gannon dominada pelo militarismo.\nEmbora o laboratório não esteja em conformidade com as Regulamentações da Illumina para Gestão de Alojamentos, ninguém se opôs, já que a maioria dos móveis foi construída por Algol usando materiais reciclados. Diz-se que qualquer pessoa que visite o laboratório pode dormir profundamente ao som dos zumbidos eletrônicos ao fundo.",
  str_loading_h_desc122 = "Muitos anos atrás, quando os suprimentos eram escassos na Federação Illumina, jovens cientistas idealistas discutiam o futuro dos Aurorianos dia e noite neste pequeno laboratório.\nSe houvesse um fim para os Aurorianos, cada discussão e pergunta levantada era para impedir que isso acontecesse. No entanto, as mesas de laboratório, o chão e as estruturas de aço que uma vez foram reflexos dessa sabedoria desde então desapareceram.",
  str_loading_h_desc123 = "Quando alguém em Illumina olha para cima na cidade subterrânea, sabe que o raio de luz penetrante é um presente do \"mundo civilizado\" para Gannon. Vez após vez, Gannon suportou invasões de Eclipsitas, assim, o povo de Illumina se esforça para repelir os invasores, esperando que um dia possam ressurgir e desfrutar do sol em paz.\nNo entanto, esse raio também é a despedida final do mundo civilizado. Com a Crise Darkover iminente, será que Illumina conseguirá manter sua casa?",
  str_loading_h_desc124 = "Um armazém copioso, vazio e frio, pungente com o cheiro de soluções. O espaço aberto parece ter abrigado armas enormes, porém letais. Aqueles que pisam aqui pela primeira vez nunca se sentiram tão insignificantes.\nUma máquina em funcionamento contínuo age como uma ligação entre o passado e o presente. Aproxime-se da complexa e rangente mesa de laboratório biológico e você quase pode ouvir os gritos das inúmeras vidas inocentes que receberam sua \"renascença\" aqui.",
  str_loading_h_desc125 = "Uma fissura gigante sem qualquer sinal de vida. Julgando pelas rachaduras, é um fenômeno antigo da Zona Escura. Explosões violentas no passado também foram evidentes, deixando apenas um poço negro como breu, pedregulhos flutuantes e terra queimada. Na superfície, as rachaduras estão se ramificando ainda mais.\nO que aconteceu aqui? Ou, o que ainda está acontecendo?",
  str_loading_h_desc126 = "Escuridão infinita e silêncio como se o tempo tivesse parado. De repente, um rio inescrutável se estende lentamente do remoto \"horizonte\" como em uma pintura. Esta é uma paisagem fantástica nunca antes vista nos mapas de Astra. Sua aparição envolve a realidade do mundo em ainda mais mistério.\nOnde é a fonte deste rio? É real? Por que é que quando você mexe na água, mudanças inesperadas acontecem em algum lugar do mundo?",
  str_loading_c_h_name127 = "Reino de Ji",
  str_loading_c_h_name128 = "Crise Costeira no Reino de Ji",
  str_loading_c_h_name129 = "Festival da Primavera",
  str_loading_e_h_name127 = "Reino da Água Comércio e Navegação",
  str_loading_e_h_name128 = "Donzela do Dragão, Eclipsitas e o Selo",
  str_loading_e_h_name129 = "Ano Novo de Longzhou",
  str_loading_h_desc127 = "Um reino vassalo no oeste de Longzhou. É repleto de muitos rios entrecruzados e, como tal, possui um sistema de transporte aquático bem desenvolvido, com rotas de navios por grande parte de Longzhou, tornando-se um centro de transporte desde os tempos antigos. Com o florescimento do comércio, tornou-se naturalmente o centro da economia. Sua capital, a cidade de Haojin, é extremamente próspera e abriga muitas famílias ricas de comerciantes, incluindo a Lin Guild.",
  str_loading_h_desc128 = "Centenas de anos atrás, os remanescentes dos Eclipsitas enterrados nas águas costeiras do Reino Ji uma vez corromperam os parentes da Donzela do Dragão, um dragão serpente negro. A Donzela do Dragão teve que danificá-lo severamente, selando a caverna do mar para prevenir o transbordamento do poder dos Eclipsitas. Devido à negligência do reino sobre o grande ritual, o selo foi destruído, libertando os Eclipsitas para causar o caos. O Reino Ji, embora tenha mobilizado suas forças para responder, sofreu perdas substanciais.",
  str_loading_h_desc129 = "O Festival da Primavera é o festival mais importante no continente de Longzhou. A família real organizaria banquetes para convidados estimados, enquanto os cidadãos se reuniam para lazer e para se atualizarem. No Reino de Ji, os locais organizam feiras de templo, prestam homenagem à Donzela do Dragão e afastam a besta Nian durante o festival, esperando por saúde e boa sorte no próximo ano. Alguns comerciantes contratam demônios para realizar shows temáticos sobre o ritual de perseguição à besta, adicionando um toque de diversão ao início do ano novo.",
  str_loading_c_h_name205 = "Sala de Controle de Aeronaves da Federação Illumina",
  str_loading_c_h_name206 = "Fronteira da Nevasca",
  str_loading_c_h_name207 = "Caverna da Fronteira",
  str_loading_c_h_name208 = "Altar Ancestral",
  str_loading_c_h_name209 = "Muralhas do Castelo",
  str_loading_e_h_name205 = "Frio e imponente, com um rico aroma de metal persistindo no ar.",
  str_loading_e_h_name206 = "A raramente visitada fronteira noroeste de Northland.",
  str_loading_e_h_name207 = "Uma caverna antiga velada por camadas de gelo.",
  str_loading_e_h_name208 = "O misterioso solo sagrado protegido por gerações da tribo Snow Fox.",
  str_loading_e_h_name209 = "Um antigo castelo devastado pela guerra.",
  str_loading_h_desc205 = "Embora não seja tão espaçoso quanto a Sala de Controle do Colosso, este lugar é suficiente para acomodar uma equipe de expedição de tamanho médio. Suas paredes são cobertas com painéis de instrumentos e telas intrincados, registrando com precisão vários parâmetros e dados da aeronave. À medida que os ponteiros no painel de instrumentos oscilam constantemente, o som mecânico rítmico e suave parece ressoar com a frequência de um cálculo mecânico gigante no fundo de uma Subcidade Illumina.",
  str_loading_h_desc206 = "Sob o céu sombrio de neve, o outrora infinito deserto nevado parece ter um fim. Montanhas altas se erguem como um muro ao longe, dividindo este lugar do mundo exterior. No entanto, a desolada Floresta Nevosa enfrenta outro terrível assalto, com casas reduzidas a escombros, pinheiros nevados brutalmente quebrados, e a neve manchada com grandes manchas de sangue vermelho-negro... Parece que ninguém sabe ou se importa com as criaturas que vivem aqui.",
  str_loading_h_desc207 = "A caverna gelada apresenta uma estrutura labiríntica e complexa. Algumas paredes de gelo se erguem verticalmente, enquanto outras são baixas e estreitas, forçando os transeuntes a se curvarem. Uma luz fraca filtra através dos cristais de gelo, lançando sombras salpicadas e envolvendo a caverna em uma sombra serena e prateada. Colunas de gelo altas e robustas, juntamente com flores de gelo nas paredes da caverna, se transformam em formas peculiares, prontas para o momento em que a aurora desce.",
  str_loading_h_desc208 = "Nas profundezas da caverna escura, feixes de luz atravessam o teto, iluminando o altar abaixo, como se os criadores do altar aguardassem o despertar das três árvores sagradas. Diante do altar, há uma laje de pedra inscrita com runas antigas, detalhando a lenda das \"Três Pinheiros\". Duas estátuas de Neve Fox desgastadas pelo tempo estão de guarda, simbolizando a proteção de sua tribo ao altar. Os anciãos uma vez disseram que, apesar de parecerem congeladas por milênios, a bênção das árvores sagradas perdura.",
  str_loading_h_desc209 = "Uma rajada de vento varre as profundezas da caverna, passando por um imponente castelo antigo emergindo do chão. Na tempestade de neve furiosa, o interior do castelo brilha intensamente com fogo. Os defensores do castelo se movem, seus espíritos elevados enquanto marcham para cumprir seu antigo juramento. Seus gritos e o choque das armas baniram o frio do gelo e da neve, fazendo-os esquecer a dureza desta era.",
  str_loading_N45_Cname_01 = "Base da Chave Rediesel",
  str_loading_N45_Cname_02 = "Corredor da Linha Ley",
  str_loading_N45_Cname_03 = "Vulcão Rugindo",
  str_loading_N45_Ename_01 = "Uma base temporária estabelecida pela Rediesel Wrench depois que eles pararam de se mover.\nEficiente e conveniente.",
  str_loading_N45_Ename_02 = "Um caminho sinuoso sob o Deserto Rediesel.\nEsses passagens misteriosas estão conectadas às linhas ley do deserto.",
  str_loading_N45_Ename_03 = "Um vulcão subterrâneo que está sempre rugindo.\nEstranhamente, ele entrou em erupção há apenas 15 anos.",
  str_loading_N45_des_01 = "Devido ao ambiente árido do deserto, a Rediesel Wrench é frequentemente forçada a deixar o oásis para procurar suprimentos.\nQuando Lepidoz para, eles constroem uma base temporária no local.",
  str_loading_N45_des_02 = "Sob o Deserto de Rediesel existem muitos corredores sinuosos inexplicáveis que se estendem em todas as direções e são coletivamente chamados de corredor das linhas ley.\nNinguém sabe como eles se formaram, mas o corredor parece ter existido por muito tempo e até foi desenvolvido por um tempo. No entanto, tudo foi destruído pelo início de vários desastres.",
  str_loading_N45_des_03 = "O Vulcão Rugidor é o vulcão mais perigoso do Deserto Rediesel. Geralmente está adormecido, mas sempre faz um som rugindo. A única vez que entrou em erupção, destruiu a base original do Deserto Rediesel.\nOs membros da Rediesel Wrench temem este vulcão e não voltam lá há muitos anos.\nDe acordo com alguns dos rumores espalhados entre eles, o som rugindo pertence aos Eclipsitas que vivem no magma.",
  str_loading_N46_Cname_01 = "Presas Ocultas",
  str_loading_N46_Ename_01 = "Arcade Umbraton.\nO símbolo da comunidade de jogos de Astra.",
  str_loading_N46_des_01 = "Um fliperama fundado por jogadores experientes. Começou como um pequeno clube que atendia aos Aurorianos que tinham uma queda por consoles de jogos antigos. À medida que mais e mais jogos foram restaurados e desenvolvidos, jogadores de toda Astra foram atraídos, e logo o fliperama se tornou o principal ponto de encontro da comunidade de jogos.",
  str_loading_N47_Cname_01 = "Base: Nível da Superfície",
  str_loading_N47_Cname_02 = "Base: Passagem",
  str_loading_N47_Cname_03 = "Base: Abismo",
  str_loading_N47_Cname_04 = "Base: Ruínas",
  str_loading_N47_Cname_05 = "Ponta de Lança",
  str_loading_N47_Ename_01 = "O Tempo e a Fundação Caem Juntos",
  str_loading_N47_Ename_02 = "Eco do Espaço do Instrumento Abandonado",
  str_loading_N47_Ename_03 = "O Ponto de Ruptura das Memórias e o Turning Point da Vida",
  str_loading_N47_Ename_04 = "Local de Descanso da Ponta de Lança da Colossus Despedaçada",
  str_loading_N47_Ename_05 = "Onde Fantasmas do Passado Permanecem",
  str_loading_N47_des_01 = "Uma base experimental enterrada por Illumina. Poderia ter permanecido escondida se não fosse pela imensa força de Barton criando uma abertura.\nA frágil fundação forma um contraste gritante com as robustas muralhas da cidade de Illumina de hoje. No entanto, os segredos do passado sempre aguardam seu tempo, esperando pela pessoa certa para desvendá-los.\nEste lugar testemunhou tanto treinamentos apaixonados quanto experimentos cruéis, bem como lutas desesperadas e rebeliões ardentes.",
  str_loading_N47_des_02 = "Os instrumentos descartados atuam como guardas que obstruem o caminho dos intrusos. Vários instrumentos ainda em funcionamento espreitavam das ruínas, perturbando os pensamentos dos intrusos enquanto secretamente faziam planos. Esta é uma caverna escura que isola gritos angustiados, e um longo túnel que testa sonhadores. Se você ouvir uma voz chamando por você, talvez deva parar e ver se é o seu passado abandonado tentando alcançá-lo.",
  str_loading_N47_des_03 = "Foi um tempo de dificuldades insuportáveis, enterrando inúmeras experiências de vida abandonadas. Acima do abismo está o terreno elevado dos vencedores, e abaixo dele está o cemitério dos sacrificados. Qualquer um que deseje derrubar esse passado injusto deve mergulhar no abismo. Apenas quando seus corpos estiverem queimando e não restar carne para ser destruída, eles poderão voar para sempre.",
  str_loading_N47_des_04 = "No fundo da base experimental jaz um Colossus com uma cauda quebrada que ainda possui uma consciência tênue.Sua vontade tenaz parece estar comandando suas partes dispersas para se recompor enquanto espera o comando de um Navegador para partir em direção à sua antiga casa. Parece que ele esteve aqui por mais tempo do que toda a história da Illumina, e a verdade deste experimento é revelada por todo o equipamento experimental construído ao seu redor em um momento posterior.",
  str_loading_N47_des_05 = "Esta transação perigosa é a última pista disponível para todos os exploradores. \nAtravés de um instrumento especial, pode-se ver os dados restantes da sala de controle principal da Spearhead. Embora a sala esteja em ruínas, sua estrutura interna é mais concisa e suave comparada a Soroz, e cada painel de controle exala uma aura perigosa. Veio da Dark Zone? Seu Navegador poderia ser um Caelestite?",
  str_loading_N48_Cname_01 = "Cidade Varaki",
  str_loading_N48_Cname_02 = "Advento da Verdade",
  str_loading_N48_Cname_03 = "Tumba do Varaki",
  str_loading_N48_Cname_04 = "Castelo de Wilhelm",
  str_loading_N48_Cname_05 = "Templo da Verdade",
  str_loading_N48_Ename_01 = "Pátria da família de vampiros.",
  str_loading_N48_Ename_02 = "Grande assembleia da Verdadeira Ordem.",
  str_loading_N48_Ename_03 = "Local de descanso dos ancestrais Varaki.",
  str_loading_N48_Ename_04 = "Um castelo frio e solitário na encosta do penhasco.",
  str_loading_N48_Ename_05 = "Um salão carmesim sagrado e sinistro.",
  str_loading_N48_des_01 = "a família de vampiros, uma raça Auroriana distinta, há muito habita a cidade de Varaki, como dizem as lendas. Eles preferem a noite e têm um desejo por sangue. Suas vidas são prolongadas, muitas vezes mantendo a aparência que tinham no despertar de sua linhagem.\nOs descendentes desta família herdam o grande poder de seus antepassados quando sua linhagem é despertada. No entanto, as dolorosas memórias que acompanham este poder são o custo que devem suportar.",
  str_loading_N48_des_02 = "A cada três anos, ocorre uma noite assim—À meia-noite, os sinos do Templo da Verdade tocam, e as altas torres de sino se estendem e alcançam a lua.A lua, brilhando em vermelho-sangue, paira no céu como se o Senhor da Verdade estivesse ouvindo suas confissões no templo e compartilhando a glória e os segredos da família. Discípulos da Verdade vestem túnicas e marcham com caixões pelas ruas, entoando reverentemente o nome do Senhor, aguardando a chegada do Senhor da Verdade.",
  str_loading_N48_des_03 = "O clã Varaki considera os restos de seus ancestrais como tesouros e, em momentos específicos, os observa com o líder da família e discípulos. Além disso, os antigos caixões nas tumbas guardam muitos segredos ocultos.\nPlantas negras com um brilho místico cercam as tumbas, que, à luz da lua sangrenta, assumirão a forma semi-humana e abrirão as portas do túmulo para os escolhidos.",
  str_loading_N48_des_04 = "Na vasta e fria casa antiga, um grande caixão repousa no centro do salão, onde as flores nunca murcham e as velas nunca se apagam, como se fossem as únicas companhias do dono do caixão.\nTodos chamam o caixão de cama de gelo do vampiro. No entanto, ninguém está ciente de que alguém já deixou o barulho da cidade para trás e veio para cá, com uma alma fervendo como água quente, lendo, meditando e procurando o caminho para a Verdade sozinho.",
  str_loading_N48_des_05 = "É o lugar onde os discípulos da Verdadeira Ordem confessam e aprendem. Na noite do Advento da Verdade, os líderes da Ordem e os chefes de família lideram conjuntamente uma importante cerimônia de \"escuta\".\nOs discípulos são informados de que devem revelar seus corpos fracos e deitar no caixão com corações piedosos. Então, durante o canto do chefe da família, os ancestrais de Varaki, e até mesmo o Senhor da Verdade, descerão sobre este discípulo, falando revelação através de sua boca.",
  str_loading_c_h_name_laisha1 = "A Ilha Solitária",
  str_loading_e_h_name_laisha1 = "Terra das Antigas Ruínas",
  str_loading_h_desc_laisha1 = "Nos mares distantes, existe uma ilha solitária esquecida pelo mundo, cercada por um azul infinito e coberta por uma vegetação densa e exuberante. Ruínas antigas repousam neste berço verdejante e intocado, tendo resistido através das eras.",
  str_loading_c_h_name_laisha2 = "Aventura de Verão",
  str_loading_e_h_name_laisha2 = "Companheiros, Juntos",
  str_loading_h_desc_laisha2 = "A ilha repousa silenciosamente no fundo do mar, junto com as evidências de sua antiga glória. Agora, uma nova aventura de verão está prestes a começar.\nCompanheiros que estão ao seu lado são os tesouros mais preciosos.\nNo tempo limitado que você tem, aproveite esta aventura sem fim com seus companheiros!",
  str_loading_c_h_name_N5001 = "Porto da Cidade do Porto",
  str_loading_c_h_name_N5002 = "Aquário",
  str_loading_c_h_name_N5003 = "Fantasia do Aquário",
  str_loading_e_h_name_N5001 = "A brisa do mar sopra suavemente, e as aves migratórias continuam cantando.",
  str_loading_e_h_name_N5002 = "O mar em terra, um mundo tranquilo.",
  str_loading_e_h_name_N5003 = "O oceano no sonho, um mundo reconhecido novamente.",
  str_loading_h_desc_N5001 = "Harbour City, um raro lugar de tranquilidade em Astra.\nNo entanto, uma sensação de calma geralmente precede a agitação.\nApesar das tempestades inevitáveis, a cidade, como as ondas duradouras, sempre se recupera.",
  str_loading_h_desc_N5002 = "Os peixes vieram do mar, mas no final se estabeleceram juntos em terra.\nCom o som da concha, eles caem em um sonho tranquilo.\nE essa cena harmoniosa se torna um paraíso para os visitantes.",
  str_loading_h_desc_N5003 = "Você já sonhou? Nos sonhos, o comum se transforma no estranho. Como um quarto dos fundos sombrio e cintilante, há uma familiaridade assustadora com o desconhecido. É nesses reinos crepusculares da mente que redescobrimos o mundo que pensávamos conhecer.",
  str_loading_21001_name = "Terras da Zona Escura",
  str_loading_21001_name_title = "Meio Passo da Noite Eterna",
  str_loading_21001_desc = "Para os Aurorianos, entrar na Zona Escura é como desistir da própria vida.\nNenhuma Lúmina os apoia aqui, apenas sombras que sufocam todos.\nMas para o Eclipse, é um terreno de caça ideal.\nAinda assim, mesmo assim, os destemidos avançam através da névoa, determinados a descobrir os segredos dentro.",
  str_loading_21002_name = "Setor Inexplorado 44",
  str_loading_21002_name_title = "Terrenos de Coral",
  str_loading_21002_desc = "Uma terra sem vida invadida por corais.\nO tempo parece congelado aqui, e a luz a abandonou.\nAlguns vestígios de vida ainda podem ser encontrados em suas fronteiras.\nMas para aqueles que ainda vagam aqui, isso não importa.\nEste é um lugar amaldiçoado para repelir a luz, condenando todos os seres vivos."
}
return config
